        assert!(matches!(
            events.try_recv().map(|(_, event)| event),
            Ok(TokenEvent::Rejected { ref message, .. }) if message.contains("outside 0..1")
        ));
    }

    #[test]
    fn multi_partition_drop_joins_every_thread() {
        let exited: Vec<_> = (0..3).map(|_| Arc::new(AtomicBool::new(false))).collect();
        let (txs, joins): (Vec<_>, Vec<_>) = exited
            .iter()
            .map(|flag| {
                let (tx, mut rx) = mpsc::unbounded_channel::<SubmittedRequest>();
                let flag = Arc::clone(flag);
                let join = thread::spawn(move || {
                    while rx.blocking_recv().is_some() {}
                    flag.store(true, Ordering::SeqCst);
                });
                (tx, join)
            })
            .unzip();
        let handle = EngineHandle::new_with_join_handles(txs, joins);
        drop(handle);
        for flag in &exited {
            assert!(flag.load(Ordering::SeqCst));
        }
    }

    #[test]
    fn metrics_watches_define_scheduler_partitions() {
        let (submit_tx, _submit_rx) = mpsc::unbounded_channel::<SubmittedRequest>();
        let (_load_tx0, load_rx0) = watch::channel(SchedulerMetrics {
            num_running_reqs: 1,
            ..SchedulerMetrics::default()
        });
        let (_load_tx1, load_rx1) = watch::channel(SchedulerMetrics {
            num_waiting_reqs: 2,
            ..SchedulerMetrics::default()
        });
        let handle = EngineHandle::new(submit_tx).with_metrics_watches(vec![load_rx0, load_rx1]);

        assert_eq!(handle.scheduler_partition_count(), 2);
        assert_eq!(
            handle
                .metrics_watch_for(0)
                .expect("rank 0 watch")
                .borrow()
                .num_running_reqs,
            1
        );
        assert_eq!(
            handle
                .metrics_watch_for(1)
                .expect("rank 1 watch")
                .borrow()
                .num_waiting_reqs,
            2
        );
        assert!(handle.metrics_watch_for(2).is_none());
    }
}

