pub async fn serve_prefill_only_with_engine_count(
    engine: impl Future<Output = Result<LaunchedEngine>> + Send + 'static,
    model_path: &Path,
    served_model_name: Vec<String>,
    tool_call_parser: ParserSelection,
    port: u16,
    max_model_len: Option<u32>,
    engine_count: usize,
    shutdown: CancellationToken,
) -> Result<()> {
    serve_with_router_extension(
        engine,
        model_path,
        served_model_name,
        tool_call_parser,
        port,
        max_model_len,
        engine_count,
        shutdown,
        request_contract::prefill_only_routes,
    )
    .await
}

pub async fn serve_model_with_lora_routes(
    engine: crate::engine::Engine,
    model_id: impl Into<String>,
    served_model_name: Vec<String>,
    tool_call_parser: ParserSelection,
    lora_modules: Vec<LoraModule>,
    port: u16,
    max_model_len: u32,
    shutdown: CancellationToken,
) -> Result<()> {
    let model_id = model_id.into();
    let adapter_names = Arc::new(RwLock::new(HashSet::new()));
    // The Option is the capability: only engines that minted a LoRA channel
    // can serve these routes.
    let control = engine
        .lora
        .clone()
        .ok_or_else(|| anyhow::anyhow!("engine does not expose LoRA adapter control"))?;
    load_startup_lora_modules(&control, &adapter_names, &lora_modules).await?;
    let base_model_name = served_model_name
        .first()
        .cloned()
        .unwrap_or_else(|| model_id.clone());
    serve_model_on_host_with_router_extension(
        std::future::ready(Ok(LaunchedEngine::Stepped(engine))),
        model_id,
        served_model_name.clone(),
        tool_call_parser,
        "0.0.0.0".to_string(),
        port,
        max_model_len,
        1,
        shutdown,
        move |router| {
            let lora_router = lora_routes(control, Arc::clone(&adapter_names));
            let openai_router = lora_openai_routes(
                router.clone(),
                base_model_name,
                served_model_name,
                Arc::clone(&adapter_names),
            );
            openai_router.merge(lora_router).fallback_service(router)
        },
    )
    .await
}

async fn serve_model_on_host(
    engine: impl Future<Output = Result<LaunchedEngine>> + Send + 'static,
    model_id: String,
    served_model_name: Vec<String>,
    tool_call_parser: ParserSelection,
    host: String,
    port: u16,
    max_model_len: u32,
    engine_count: usize,
    shutdown: CancellationToken,
) -> Result<()> {
    serve_model_on_host_with_router_extension(
        engine,
        model_id,
        served_model_name,
        tool_call_parser,
        host,
        port,
        max_model_len,
        engine_count,
        shutdown,
        |router| router,
    )
    .await
}

async fn serve_model_on_host_with_router_extension<F>(
    engine: impl Future<Output = Result<LaunchedEngine>> + Send + 'static,
    model_id: String,
    served_model_name: Vec<String>,
    tool_call_parser: ParserSelection,
    host: String,
    port: u16,
    max_model_len: u32,
    engine_count: usize,
    shutdown: CancellationToken,
    extend_router: F,
) -> Result<()>
where
    F: FnOnce(Router) -> Router,
{
    ensure!(engine_count > 0, "frontend engine_count must be positive");
    let data_parallel_size = u32::try_from(engine_count)
        .map_err(|_| anyhow::anyhow!("frontend engine_count {engine_count} exceeds u32"))?;
    let namespace = local_ipc_namespace()?;
    let input_address = ipc_endpoint(&namespace, "input.sock");
    let output_address = ipc_endpoint(&namespace, "output.sock");
    // vllm-server adopts already-bound listeners (the supervisor's role in
    // upstream's Python deployment); binding them here means the bridge can
    // connect at any time, the server owns and closes the descriptors.
    let input_listener_fd = UnixListener::bind(namespace.join("input.sock"))?.into_raw_fd();
    let output_listener_fd = UnixListener::bind(namespace.join("output.sock"))?.into_raw_fd();

    // The HTTP server runs concurrently with the engine load: vllm-server
    // spends ~1s loading the tokenizer and chat templates before it waits for
    // an engine to register, so neither waits on the other. This task attaches
    // the bridge once the engine resolves and runs it to completion; on engine
    // failure it cancels the server so the error surfaces instead of hanging
    // in the registration wait.
    let server_shutdown = shutdown.child_token();
    let bridge_shutdown = shutdown.child_token();
    let engine_task = tokio::spawn({
        let server_shutdown = server_shutdown.clone();
        let bridge_shutdown = bridge_shutdown.clone();
        let input_address = input_address.clone();
        let output_address = output_address.clone();
        async move {
            let launched = match engine.await {
                Ok(launched) => launched,
                Err(error) => {
                    server_shutdown.cancel();
                    return Err(error);
                }
            };
            let mut bridges = tokio::task::JoinSet::new();
            // Stepped engines own their scheduler threads; reaped below after
            // the bridges (and with them the scheduler handles) are gone.
            let mut scheduler_joins: Vec<std::thread::JoinHandle<()>> = Vec::new();
            match launched {
                LaunchedEngine::Handle(handle) => {
                    let actual_partitions = handle.scheduler_partition_count();
                    if actual_partitions != engine_count {
                        server_shutdown.cancel();
                        anyhow::bail!(
                            "frontend declared {engine_count} engines but the resolved handle \
                             exposes {actual_partitions} scheduler partitions"
                        );
                    }
                    let servable_limit = handle.servable_len().map(|cap| max_model_len.min(cap));
                    let max_model_len = servable_limit.unwrap_or(max_model_len);
                    for engine_index in 0..engine_count {
                        let bridge = LocalEngineBridge {
                            input_address: input_address.clone(),
                            output_address: output_address.clone(),
                            handle: handle.clone(),
                            max_model_len,
                            engine_index: engine_index as u32,
                            data_parallel_size,
                            metrics_watch: handle.metrics_watch_for(engine_index),
                        };
                        let shutdown = bridge_shutdown.clone();
                        bridges.spawn(async move { (engine_index, bridge.run(shutdown).await) });
                    }
                    drop(handle);
                }
                LaunchedEngine::Stepped(engine) => {
                    let actual_schedulers = engine.schedulers.len();
                    if actual_schedulers != engine_count {
                        server_shutdown.cancel();
                        anyhow::bail!(
                            "frontend declared {engine_count} engines but the launched engine \
                             exposes {actual_schedulers} schedulers"
                        );
                    }
                    let info = engine.info;
                    let servable_limit = info.servable_len.map(|cap| max_model_len.min(cap));
                    let max_model_len = servable_limit.unwrap_or(max_model_len);
                    for (engine_index, scheduler) in engine.schedulers.into_iter().enumerate() {
                        scheduler_joins.push(scheduler.join);
                        let bridge = bridge::SteppedEngineBridge {
                            input_address: input_address.clone(),
                            output_address: output_address.clone(),
                            scheduler: scheduler.handle,
                            kv_capacity: info.kv_capacity,
                            max_model_len,
                            engine_index: engine_index as u32,
                            data_parallel_size,
                        };
                        let shutdown = bridge_shutdown.clone();

//! The step-batched wire contract between a model scheduler and a frontend.
//!
//! One scheduler step produces one [`StepOutputs`] message. Per request the
//! step carries at most one [`RequestUpdate`] — a flat record rather than an
//! event sequence, so the intra-step ordering rules of the old `TokenEvent`
//! protocol (`Scheduled` before tokens before a single terminal) are structure,
//! not convention: a `RequestUpdate` cannot express a token after its terminal.
//! Cross-step ordering is enforced on the producer side by the
//! [`super::RequestLedger`]: a request's account closes at its terminal, and
//! writes against a closed account panic.

use std::fmt;
use std::time::Instant;

use super::event::FinishReason;
use super::event::TokenLogprob;
use super::stop::StopCause;
use super::stop::StopPolicy;

/// In-process routing id for one generate request, minted by
/// [`super::SchedulerHandle::submit`] from a per-scheduler counter. `Copy` and
/// integer-keyed on purpose: the external protocol's string request id stays in
/// the protocol stack, which maps it to this id at its own boundary.
#[derive(Clone, Copy, Debug, Eq, Hash, Ord, PartialEq, PartialOrd)]
pub struct RequestId(u64);

impl RequestId {
    /// Minting ids is [`super::SchedulerHandle::submit`]'s job in production
    /// (a per-scheduler counter). Public so scheduler unit tests and tools
    /// can fabricate requests.
    pub fn new(raw: u64) -> Self {
        Self(raw)
    }

    /// Raw counter value, for logs and protocol-side maps.
    #[must_use]
    pub fn raw(self) -> u64 {
        self.0
    }
}

impl std::fmt::Display for RequestId {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(f, "req-{}", self.0)
    }
}

/// One generate request as a frontend submits it. Identity (`RequestId`),
/// queue timestamp, and the abort flag are minted at submit time and live on
/// the request's ledger account, not here.
pub struct Request {
    pub prompt_tokens: Vec<u32>,
    pub params: crate::sampler::SamplingParams,
    /// Count of leading prompt tokens that render the conversation's messages;
    /// the chat template's generation prompt follows them. The next turn of
    /// the conversation repeats exactly these tokens, so a scheduler that
    /// snapshots its state there serves that turn from the snapshot. `None`
    /// when the frontend did not measure it (a completion, or a chat body the
    /// chat layer could not read).
    pub history_tokens: Option<usize>,
    /// Where the conversation's earlier turns ended, newest first: the
    /// `history_tokens` of the requests that carried them, as the chat layer
    /// re-measures them from the messages. Each is a point an earlier turn's
    /// snapshot may be found at, by a scheduler that keeps snapshots beyond
    /// the one that made them; strictly less than `history_tokens`. Empty
    /// when the frontend did not measure them.
    pub history_marks: Vec<usize>,
    pub stop_policy: StopPolicy,
    pub max_tokens: usize,
    pub lora_adapter: Option<String>,
    /// Opaque router/P-D metadata from the request's
    /// `vllm_xargs.kv_transfer_params`.
    pub kv_transfer_params: Option<serde_json::Value>,
    /// Completion top-k count: None disables scoring; Some(0) scores the chosen token.
    pub logprobs: Option<usize>,
    /// Prompt top-k count, independent of completion scoring; Some(0) scores each prompt token.
    pub prompt_logprobs: Option<usize>,
    /// Trace context of the caller's request span, when tracing is on. The
    /// model scheduler opens its queue/prefill/decode spans as children of
    /// this. `None` when tracing is disabled.
    pub trace_parent: Option<fastrace::collector::SpanContext>,
    /// External request name for scheduler-side logs only; never used for
    /// routing (that is [`RequestId`]).
    pub client_label: Option<std::sync::Arc<str>>,
}

/// One submitted request as the scheduler receives it: the id of its open
/// ledger account, and the payload. The id is minted by
/// [`super::SchedulerHandle::submit`]; a payload never carries one of its own.
pub struct QueuedRequest {
    pub id: RequestId,
    pub request: Request,
}

/// Everything one scheduler step produced, in one message. Empty `updates`
/// notify the frontend of changed metrics, for example after cancellation.
/// A step with no request updates or metric changes sends nothing.
#[derive(Debug, Default)]
pub struct StepOutputs {
    pub updates: Vec<RequestUpdate>,
}

/// Everything that happened to one request within one step, flattened. A
/// consumer folds the sections in field order: admission facts, then new
/// tokens, then the terminal.
#[derive(Debug)]
pub struct RequestUpdate {
    pub id: RequestId,
    /// Present exactly once per request lifetime, in the step whose iteration
    /// admitted it.
    pub scheduled: Option<ScheduledInfo>,
    /// Tokens committed this step. Multi-token spans (speculative/MTP commits)
    /// arrive together; a pure-prefill step contributes none.
    pub tokens: Vec<u32>,
    /// Parallel to `tokens` (same length whenever non-empty is possible; all
    /// `None` when logprobs were not requested).
    pub logprobs: Vec<Option<TokenLogprob>>,
    /// Prompt tokens served from a prefix cache, reported in the step where
    /// the scheduler learns it (first prefill chunk), not at admission —
    /// admission-time `Scheduled` cannot know it yet.
    pub cached_tokens: Option<usize>,
    /// Echoed prompt, once, when the request's prefill completes.
    pub prompt_echo: Option<PromptEcho>,
    /// Opaque P/D handoff metadata forwarded through the protocol stack's
    /// `kv_transfer_params` response field.
    pub kv_transfer: Option<serde_json::Value>,
    /// End of the request's lifetime. No later step mentions this id again.
    pub terminal: Option<Terminal>,
}

impl RequestUpdate {
    pub(crate) fn empty(id: RequestId) -> Self {
        Self {
            id,
            scheduled: None,
            tokens: Vec::new(),
            logprobs: Vec::new(),
            cached_tokens: None,
            prompt_echo: None,
            kv_transfer: None,
            terminal: None,
        }
    }

    /// An update that carries no observable fact (possible when a request's
    /// only activity this step was bookkeeping). The ledger drops these
    /// rather than shipping empty records.
    pub(crate) fn is_vacant(&self) -> bool {
        self.scheduled.is_none()
            && self.tokens.is_empty()
            && self.cached_tokens.is_none()
            && self.prompt_echo.is_none()
            && self.kv_transfer.is_none()
            && self.terminal.is_none()
    }
}

/// Admission facts stamped by the contract layer, never by model code:
/// `queued_at` at [`super::SchedulerHandle::submit`], `scheduled_at` at
/// [`super::RequestLedger::admit`]. Monotonic `Instant`s — the wall-clock

